/* ---------- TicketDetailModal ---------- */

/* Ficha completa de una reserva: letra grande, un detalle por renglón (label
   arriba, valor abajo en grande), para que se lea bien aunque ocupe más
   espacio. Desde acá se puede editar, imprimir o "descargar" (el diálogo de
   impresión del navegador permite guardar como PDF sin depender de ninguna
   librería nueva), y también bajar un .txt plano como respaldo simple. */
/* ---------- Estado del vuelo en tiempo real (aviationstack) ----------
   Requiere una API key gratuita de https://aviationstack.com/ (plan free:
   500 consultas/mes) guardada como variable de entorno VITE_AVIATIONSTACK_KEY
   en Vercel. Si no está configurada, el bloque simplemente no se muestra. */
const AVIATIONSTACK_KEY = (typeof import.meta !== "undefined" && import.meta.env && import.meta.env.VITE_AVIATIONSTACK_KEY) || "";

const FLIGHT_STATUS_LABELS = {
  scheduled: { label: "Programado", color: "#1A657B" },
  active: { label: "En vuelo", color: "#0A2C47" },
  landed: { label: "Aterrizó", color: "#3E7A4E" },
  cancelled: { label: "Cancelado", color: "#B7391F" },
  incident: { label: "Incidente", color: "#B7391F" },
  diverted: { label: "Desviado", color: "#B99B6B" },
};

function FlightStatus({ flightNumber }) {
  const [status, setStatus] = useState(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState("");

  const clean = (flightNumber || "").replace(/\s+/g, "").toUpperCase();

  const fetchStatus = async () => {
    if (!clean) return;
    setLoading(true);
    setError("");
    setStatus(null);
    try {
      const res = await fetch(`https://api.aviationstack.com/v1/flights?access_key=${AVIATIONSTACK_KEY}&flight_iata=${encodeURIComponent(clean)}`);
      const data = await res.json();
      if (data.error) throw new Error(data.error.message || "No se pudo consultar el vuelo.");
      const flight = (data.data || [])[0];
      if (!flight) throw new Error("No se encontró información para este vuelo (puede que todavía no esté programado en el sistema, o que ya haya pasado hace mucho).");
      setStatus(flight);
    } catch (e) {
      setError(e.message || "No se pudo consultar el estado del vuelo.");
    }
    setLoading(false);
  };

  if (!AVIATIONSTACK_KEY || !clean) return null;

  const info = status && FLIGHT_STATUS_LABELS[status.flight_status];

  return (
    <div className="no-print flex flex-col gap-2 rounded-xl p-4" style={{ background: C.card, border: `1px solid ${C.platinum}` }}>
      <div className="flex items-center justify-between">
        <span className="text-[12px] uppercase tracking-wide" style={{ color: C.inkSoft }}>Estado del vuelo {clean}</span>
        <button onClick={fetchStatus} disabled={loading} className="flex items-center gap-1.5 text-[12px] font-semibold" style={{ color: C.copper }}>
          {loading ? <Loader2 size={13} className="animate-spin" /> : <Plane size={13} />} {status ? "Actualizar" : "Consultar"}
        </button>
      </div>

      {error && <p className="text-[12px]" style={{ color: "#B7391F" }}>{error}</p>}

      {status && (
        <div className="flex flex-col gap-2 mt-1">
          {info && (
            <span className="inline-flex w-fit items-center text-[11px] font-bold uppercase px-2.5 py-1 rounded-full text-white" style={{ background: info.color }}>
              {info.label}
            </span>
          )}
          <div className="flex gap-4">
            <div>
              <div className="text-[10px] uppercase" style={{ color: C.inkSoft }}>Salida</div>
              <div className="text-[14px] font-bold font-mono" style={{ color: C.ink }}>
                {status.departure?.estimated ? new Date(status.departure.estimated).toLocaleString("es-AR", { day: "2-digit", month: "2-digit", hour: "2-digit", minute: "2-digit" }) : "—"}
              </div>
              {status.departure?.terminal && <div className="text-[11px]" style={{ color: C.inkSoft }}>Terminal {status.departure.terminal}{status.departure.gate ? ` · Puerta ${status.departure.gate}` : ""}</div>}
              {status.departure?.delay ? <div className="text-[11px]" style={{ color: "#B7391F" }}>Demora {status.departure.delay} min</div> : null}
            </div>
            <div>
              <div className="text-[10px] uppercase" style={{ color: C.inkSoft }}>Llegada</div>
              <div className="text-[14px] font-bold font-mono" style={{ color: C.ink }}>
                {status.arrival?.estimated ? new Date(status.arrival.estimated).toLocaleString("es-AR", { day: "2-digit", month: "2-digit", hour: "2-digit", minute: "2-digit" }) : "—"}
              </div>
              {status.arrival?.terminal && <div className="text-[11px]" style={{ color: C.inkSoft }}>Terminal {status.arrival.terminal}{status.arrival.gate ? ` · Puerta ${status.arrival.gate}` : ""}</div>}
              {status.arrival?.delay ? <div className="text-[11px]" style={{ color: "#B7391F" }}>Demora {status.arrival.delay} min</div> : null}
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

function TicketDetailModal({ item, day, onClose, onEdit }) {
  const style = TYPE_STYLES[item.type];
  const Icon = style.icon;
  const mapsHref = `https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(item.maps_query || "")}`;

  const downloadText = () => {
    const lines = [
      item.title,
      `${style.label} · ${item.source || ""}`,
      day ? `Día ${day.day_number} · ${day.date_label} · ${day.city}` : null,
      "",
      ...(item.meta || []).map((m) => `${m.label}: ${m.value}`),
      "",
      `Código: ${item.code}`,
      item.maps_query ? `Ubicación: ${item.maps_query}` : null,
      item.attachment_url ? `Comprobante: ${item.attachment_url}` : null,
    ].filter(Boolean);
    const blob = new Blob([lines.join("\n")], { type: "text/plain;charset=utf-8" });
    const url = URL.createObjectURL(blob);
    const a = document.createElement("a");
    a.href = url;
    a.download = `${item.title.replace(/[^a-z0-9]+/gi, "_")}.txt`;
    a.click();
    URL.revokeObjectURL(url);
  };

  return (
    <div className="fixed inset-0 z-50 overflow-y-auto print-ticket" style={{ background: C.bg }}>
      <header className="no-print px-5 pt-6 pb-4 flex items-center justify-between" style={{ borderBottom: `1px solid ${C.platinum}` }}>
        <button onClick={onClose} style={{ color: C.inkSoft }} aria-label="Cerrar"><ArrowLeft size={20} /></button>
        <button onClick={() => onEdit(item)} className="flex items-center gap-1.5 text-[13px] font-semibold" style={{ color: C.ink }}>
          <Pencil size={15} /> Editar
        </button>
      </header>

      <main className="px-5 py-6 flex flex-col gap-5 max-w-xl mx-auto">
        <div className="flex items-center gap-2">
          <Icon size={22} color={style.accent} />
          <span className="text-[14px] font-bold uppercase tracking-wide" style={{ color: style.accent }}>{style.label}</span>
          <span className="text-[13px] ml-auto" style={{ color: C.inkSoft }}>{item.source}</span>
        </div>

        <h1 className="text-[26px] font-extrabold leading-tight" style={{ fontFamily: FONT_TITLE, color: C.ink }}>{item.title}</h1>

        {day && (
          <p className="text-[14px]" style={{ color: C.inkSoft }}>
            Día {day.day_number} · {day.date_label} · {day.city}
          </p>
        )}

        {item.meta?.length > 0 && (
          <div className="flex flex-col gap-4 rounded-xl p-4" style={{ background: C.card, border: `1px solid ${C.platinum}` }}>
            {item.meta.map((m, i) => (
              <div key={i} className="flex flex-col gap-0.5" style={{ borderBottom: i < item.meta.length - 1 ? `1px dotted ${C.platinum}` : "none", paddingBottom: i < item.meta.length - 1 ? 12 : 0 }}>
                <span className="text-[12px] uppercase tracking-wide" style={{ color: C.inkSoft }}>{m.label}</span>
                <span className="text-[20px] font-bold font-mono" style={{ color: C.ink }}>{m.value}</span>
              </div>
            ))}
          </div>
        )}

        {item.type === "flight" && (
          <FlightStatus flightNumber={(item.meta || []).find((m) => m.label === "Número de vuelo")?.value} />
        )}

        <div className="flex flex-col gap-2 rounded-xl p-4" style={{ background: C.card, border: `1px solid ${C.platinum}` }}>
          <span className="text-[12px] uppercase tracking-wide" style={{ color: C.inkSoft }}>Código de reserva</span>
          <span className="text-[22px] font-bold font-mono" style={{ color: C.ink }}>{item.code}</span>
        </div>

        <div className="no-print flex gap-2 flex-wrap">
          {item.maps_query && (
            <a href={mapsHref} target="_blank" rel="noreferrer" className="inline-flex items-center gap-1.5 text-[13px] font-semibold px-3 py-2 rounded-md" style={{ color: C.ink, background: C.platinum }}>
              <MapPin size={14} /> Cómo llegar
            </a>
          )}
          {item.attachment_url && (
            <a href={item.attachment_url} target="_blank" rel="noreferrer" className="inline-flex items-center gap-1.5 text-[13px] font-semibold px-3 py-2 rounded-md" style={{ color: "#fff", background: C.lightBeige }}>
              <Paperclip size={14} /> Comprobante
            </a>
          )}
        </div>

        <div className="no-print flex flex-col gap-2 mt-2">
          <button onClick={() => window.print()} className="w-full flex items-center justify-center gap-1.5 text-[14px] font-semibold text-white py-3.5 rounded-xl" style={{ background: C.copper }}>
            <FileText size={16} /> Imprimir / Guardar como PDF
          </button>
          <button onClick={downloadText} className="w-full flex items-center justify-center gap-1.5 text-[13px] font-semibold py-2.5 rounded-xl" style={{ background: C.wheat, color: C.ink }}>
            <Paperclip size={14} /> Descargar como texto
          </button>
        </div>
      </main>
    </div>
  );
}

/* ---------- TripView ---------- */

function TripView({ tripId, onBack }) {
  const [trip, setTrip] = useState(null);
  const [days, setDays] = useState([]);
  const [selectedDay, setSelectedDay] = useState(null);
  const [loading, setLoading] = useState(true);
  const [offline, setOffline] = useState(false);
  const [showAdd, setShowAdd] = useState(false);
  const [showImport, setShowImport] = useState(false);
  const [showEdit, setShowEdit] = useState(false);
  const [editingItem, setEditingItem] = useState(null);
  const [viewingItem, setViewingItem] = useState(null);
  const [copied, setCopied] = useState(false);

  const cacheKey = `trip:${tripId}`;

  const load = async () => {
    setLoading(true);
    try {
      const { data: t, error: tErr } = await supabase.from("trips").select("*").eq("id", tripId).single();
      if (tErr) throw tErr;
      const { data: d, error: dErr } = await supabase
        .from("trip_days")
        .select("*, trip_items(*)")
        .eq("trip_id", tripId)
        .order("day_number");
      if (dErr) throw dErr;
      setTrip(t);
      setDays(d || []);
      setOffline(false);
      if (d?.length && !selectedDay) setSelectedDay(d[0].day_number);
      writeCache(cacheKey, { trip: t, days: d || [] });
    } catch (err) {
      const cached = readCache(cacheKey);
      if (cached) {
        setTrip(cached.trip);
        setDays(cached.days);
        setOffline(true);
        if (cached.days?.length && !selectedDay) setSelectedDay(cached.days[0].day_number);
      }
    }
    setLoading(false);
  };

  useEffect(() => { load(); }, [tripId]);

  if (loading || !trip) {
    return <div className="min-h-screen flex items-center justify-center" style={{ background: C.bg }}><Loader2 className="animate-spin" color={C.copper} /></div>;
  }

  const dayData = days.find((d) => d.day_number === selectedDay) || days[0];
  const copyCode = () => { navigator.clipboard.writeText(trip.id); setCopied(true); setTimeout(() => setCopied(false), 1500); };

  const destinations = [...new Set(days.map((d) => d.city).filter((c) => c && c !== "Sin definir"))];
  const dateStart = days[0]?.date_label;
  const dateEnd = days[days.length - 1]?.date_label;
  const dateRangeLabel = dateStart && dateEnd
    ? (dateStart === dateEnd ? dateStart : `${dateStart} → ${dateEnd}`)
    : null;

  if (showAdd) {
    return <AddItem trip={trip} days={days} initialDay={selectedDay} onCancel={() => setShowAdd(false)} onSaved={async () => { setShowAdd(false); await load(); }} />;
  }

  if (showImport) {
    return <BulkImport trip={trip} days={days} onCancel={() => setShowImport(false)} onSaved={async () => { setShowImport(false); await load(); }} />;
  }

  if (editingItem) {
    return (
      <EditItem
        item={editingItem}
        day={days.find((d) => d.id === editingItem.day_id) || dayData}
        days={days}
        onCancel={() => setEditingItem(null)}
        onSaved={async () => { setEditingItem(null); await load(); }}
      />
    );
  }

  if (viewingItem) {
    const viewingDay = days.find((d) => d.id === viewingItem.day_id) || dayData;
    return (
      <TicketDetailModal
        item={viewingItem}
        day={viewingDay}
        onClose={() => setViewingItem(null)}
        onEdit={(item) => { setViewingItem(null); setEditingItem(item); }}
      />
    );
  }

  const closeEdit = async (didSave) => {
    setShowEdit(false);
    if (didSave) { setSelectedDay(null); await load(); }
  };

  return (
    <div className="min-h-screen" style={{ background: C.bg }}>
      <header className="px-5 pt-6 pb-4" style={{ borderBottom: `1px solid ${C.platinum}` }}>
        <div className="flex items-center justify-between mb-2">
          <button onClick={onBack} style={{ color: C.inkSoft }}><ArrowLeft size={18} /></button>
          <LogoMark size={20} />
        </div>
        <div className="flex items-center gap-2">
          <h1 className="text-[30px] font-extrabold leading-none" style={{ fontFamily: FONT_TITLE, color: C.ink }}>{trip.name}</h1>
          <button onClick={() => setShowEdit(true)} disabled={offline} className="mb-1 disabled:opacity-30" style={{ color: C.inkSoft }} aria-label="Editar viaje">
            <Pencil size={15} />
          </button>
        </div>
        <p className="text-[12px] mt-1.5" style={{ color: C.inkSoft }}>de {trip.owner_name}</p>

        {(destinations.length > 0 || dateRangeLabel) && (
          <div className="mt-3 flex flex-col gap-1.5 rounded-xl p-3" style={{ background: C.card, border: `1px solid ${C.platinum}` }}>
            {destinations.length > 0 && (
              <div className="flex items-start gap-2">
                <MapPin size={14} color={C.copper} className="mt-0.5 flex-shrink-0" />
                <div>
                  <div className="text-[9px] uppercase tracking-widest" style={{ color: C.inkSoft }}>Destinos</div>
                  <div className="text-[13px] font-semibold" style={{ color: C.ink }}>{destinations.join(" · ")}</div>
                </div>
              </div>
            )}
            {dateRangeLabel && (
              <div className="flex items-start gap-2">
                <Compass size={14} color={C.copper} className="mt-0.5 flex-shrink-0" />
                <div>
                  <div className="text-[9px] uppercase tracking-widest" style={{ color: C.inkSoft }}>Fechas</div>
                  <div className="text-[13px] font-semibold font-mono" style={{ color: C.ink }}>{dateRangeLabel}</div>
                </div>
              </div>
            )}
          </div>
        )}

        <div className="flex items-center justify-end mt-2">
          <button onClick={copyCode} className="flex items-center gap-1 text-[11px] font-mono px-2 py-1 rounded-md" style={{ background: C.platinum, color: C.ink }}>
            <Copy size={11} /> {copied ? "¡Copiado!" : trip.id}
          </button>
        </div>
      </header>

      <OfflineBanner show={offline} />

      <div className="flex gap-2 px-5 py-4 overflow-x-auto" style={{ borderBottom: `1px solid ${C.platinum}` }}>
        {days.map((d) => (
          <button key={d.day_number} onClick={() => setSelectedDay(d.day_number)}
            className="flex-shrink-0 flex flex-col items-center px-3.5 py-2 rounded-xl"
            style={{ background: d.day_number === selectedDay ? C.copper : "transparent", border: `1px solid ${d.day_number === selectedDay ? C.copper : C.platinum}`, color: d.day_number === selectedDay ? "#fff" : C.inkSoft }}>
            <span className="text-[9px] uppercase">Día {d.day_number}</span>
            <span className="text-[13px] font-bold font-mono">{d.date_label}</span>
          </button>
        ))}
      </div>

      <main className="px-5 py-5">
        {dayData && (
          <>
            <div className="flex items-center gap-2 mb-4">
              <ChevronRight size={16} color={C.copper} />
              <h2 className="text-[15px] font-bold" style={{ color: C.ink }}>{dayData.city}</h2>
            </div>
            <div className="flex flex-col gap-3">
              {(dayData.trip_items || []).map((item) => (
                <TicketCard key={item.id} item={item} onEdit={offline ? null : setEditingItem} onView={setViewingItem} />
              ))}
              {(dayData.trip_items || []).length === 0 && <p className="text-[13px]" style={{ color: C.inkSoft }}>Sin reservas todavía.</p>}
            </div>
          </>
        )}
        <button onClick={() => setShowAdd(true)} disabled={offline} className="mt-4 w-full flex items-center justify-center gap-1.5 text-[13px] font-semibold py-3 rounded-xl disabled:opacity-40" style={{ background: C.wheat, color: C.ink }}>
          <Plus size={15} /> Agregar reserva
        </button>
        <button onClick={() => setShowImport(true)} disabled={offline} className="mt-2 w-full flex items-center justify-center gap-1.5 text-[13px] font-semibold py-3 rounded-xl disabled:opacity-40" style={{ background: C.card, color: C.ink, border: `1px dashed ${C.platinum}` }}>
          <FileText size={15} /> Importar itinerario (JSON)
        </button>
        {offline ? (
          <div className="mt-4 flex items-center gap-2 text-[11px]" style={{ color: C.inkSoft }}>
            <WifiOff size={13} /> Viendo la copia guardada del {trip.name}; agregar reservas necesita conexión.
          </div>
        ) : (
          <div className="mt-4 flex items-center gap-2 text-[11px]" style={{ color: C.inkSoft }}>
            <Check size={13} /> Sincronizado con Supabase.
          </div>
        )}
      </main>

      <EditTripModal
        open={showEdit}
        trip={trip}
        days={days}
        onCancel={() => closeEdit(false)}
        onSaved={() => closeEdit(true)}
      />
    </div>
  );
}

/* ---------- AddItem ---------- */

/* Campos específicos por tipo de reserva. Cada uno arma su propio arreglo de
   { label, value } que termina en trip_items.meta, así que TicketCard no
   necesita cambios: ya sabe renderizar cualquier lista de meta. */
function useTypeFields(type, initial = {}) {
  const [airline, setAirline] = useState(initial.airline || "");
  const [flightNumber, setFlightNumber] = useState(initial.flightNumber || "");
  const [departureAirport, setDepartureAirport] = useState(initial.departureAirport || "");
  const [departureTerminal, setDepartureTerminal] = useState(initial.departureTerminal || "");
  const [departureTime, setDepartureTime] = useState(initial.departureTime || "");
  const [arrivalAirport, setArrivalAirport] = useState(initial.arrivalAirport || "");
  const [arrivalTerminal, setArrivalTerminal] = useState(initial.arrivalTerminal || "");
  const [arrivalDate, setArrivalDate] = useState(initial.arrivalDate || "");
  const [arrivalTime, setArrivalTime] = useState(initial.arrivalTime || "");
  const [boardingTime, setBoardingTime] = useState(initial.boardingTime || "");
  const [hasConnection, setHasConnection] = useState(initial.hasConnection || false);
  const [connectionDetail, setConnectionDetail] = useState(initial.connectionDetail || "");
  const [baggageIncluded, setBaggageIncluded] = useState(initial.baggageIncluded || "no_especificado");
  const [checkinDone, setCheckinDone] = useState(initial.checkinDone || false);

  const [checkInDateTime, setCheckInDateTime] = useState(initial.checkInDateTime || "");
  const [checkOutDateTime, setCheckOutDateTime] = useState(initial.checkOutDateTime || "");
  const [roomType, setRoomType] = useState(initial.roomType || "");

  const [operator, setOperator] = useState(initial.operator || "");
  const [seat, setSeat] = useState(initial.seat || "");

  const [activityTime, setActivityTime] = useState(initial.activityTime || "");
  const [duration, setDuration] = useState(initial.duration || "");
  const [meetingPoint, setMeetingPoint] = useState(initial.meetingPoint || "");

  const buildMeta = () => {
    const meta = [];
    if (type === "flight") {
      if (airline) meta.push({ label: "Aerolínea", value: airline });
      if (flightNumber) meta.push({ label: "Número de vuelo", value: flightNumber });
      if (departureAirport) meta.push({ label: "Aeropuerto de salida", value: departureAirport });
      if (departureTerminal) meta.push({ label: "Terminal de salida", value: departureTerminal });
      if (departureTime) meta.push({ label: "Hora de salida", value: departureTime });
      if (arrivalAirport) meta.push({ label: "Aeropuerto de llegada", value: arrivalAirport });
      if (arrivalTerminal) meta.push({ label: "Terminal de llegada", value: arrivalTerminal });
      if (arrivalDate) meta.push({ label: "Fecha de llegada", value: arrivalDate });
      if (arrivalTime) meta.push({ label: "Hora de llegada", value: arrivalTime });
      if (boardingTime) meta.push({ label: "Embarque", value: boardingTime });
      meta.push({ label: "Escalas", value: hasConnection ? (connectionDetail || "Sí") : "Directo" });
      if (baggageIncluded !== "no_especificado") {
        meta.push({ label: "Equipaje incluido", value: baggageIncluded === "si" ? "Sí" : "No" });
      }
      meta.push({ label: "Check-in", value: checkinDone ? "Hecho" : "Pendiente" });
    } else if (type === "hotel") {
      if (checkInDateTime) meta.push({ label: "Check-in", value: checkInDateTime });
      if (checkOutDateTime) meta.push({ label: "Check-out", value: checkOutDateTime });
      if (roomType) meta.push({ label: "Habitación", value: roomType });
    } else if (type === "transport") {
      if (operator) meta.push({ label: "Empresa", value: operator });
      if (departureTime) meta.push({ label: "Salida", value: departureTime });
      if (arrivalTime) meta.push({ label: "Llegada", value: arrivalTime });
      if (seat) meta.push({ label: "Asiento", value: seat });
    } else if (type === "activity") {
      if (activityTime) meta.push({ label: "Hora", value: activityTime });
      if (duration) meta.push({ label: "Duración", value: duration });
      if (meetingPoint) meta.push({ label: "Punto de encuentro", value: meetingPoint });
    }
    return meta;
  };

  return {
    fields: {
      airline, setAirline, flightNumber, setFlightNumber,
      departureAirport, setDepartureAirport, departureTerminal, setDepartureTerminal,
      departureTime, setDepartureTime,
      arrivalAirport, setArrivalAirport, arrivalTerminal, setArrivalTerminal,
      arrivalDate, setArrivalDate, arrivalTime, setArrivalTime,
      boardingTime, setBoardingTime, hasConnection, setHasConnection, connectionDetail, setConnectionDetail,
      baggageIncluded, setBaggageIncluded, checkinDone, setCheckinDone,
      checkInDateTime, setCheckInDateTime, checkOutDateTime, setCheckOutDateTime, roomType, setRoomType,
      operator, setOperator, seat, setSeat,
      activityTime, setActivityTime, duration, setDuration, meetingPoint, setMeetingPoint,
    },
    buildMeta,
  };
}

/* Reconstruye los valores iniciales de useTypeFields a partir del meta[]
   ya guardado en un trip_item, para poder precargar el formulario al editar. */
function parseInitialFields(type, meta) {
  const byLabel = Object.fromEntries((meta || []).map((m) => [m.label, m.value]));
  const initial = {};
  if (type === "flight") {
    initial.airline = byLabel["Aerolínea"] || "";
    initial.flightNumber = byLabel["Número de vuelo"] || "";
    initial.departureAirport = byLabel["Aeropuerto de salida"] || "";
    initial.departureTerminal = byLabel["Terminal de salida"] || "";
    initial.departureTime = byLabel["Hora de salida"] || byLabel["Salida"] || "";
    initial.arrivalAirport = byLabel["Aeropuerto de llegada"] || "";
    initial.arrivalTerminal = byLabel["Terminal de llegada"] || "";
    initial.arrivalDate = byLabel["Fecha de llegada"] || "";
    initial.arrivalTime = byLabel["Hora de llegada"] || byLabel["Llegada"] || "";
    initial.boardingTime = byLabel["Embarque"] || "";
    const escalas = byLabel["Escalas"];
    initial.hasConnection = !!escalas && escalas !== "Directo";
    initial.connectionDetail = initial.hasConnection ? escalas : "";
    const baggage = byLabel["Equipaje incluido"];
    initial.baggageIncluded = baggage === "Sí" ? "si" : baggage === "No" ? "no" : "no_especificado";
    initial.checkinDone = byLabel["Check-in"] === "Hecho";
  } else if (type === "hotel") {
    initial.checkInDateTime = byLabel["Check-in"] || "";
    initial.checkOutDateTime = byLabel["Check-out"] || "";
    initial.roomType = byLabel["Habitación"] || "";
  } else if (type === "transport") {
    initial.operator = byLabel["Empresa"] || "";
    initial.departureTime = byLabel["Salida"] || "";
    initial.arrivalTime = byLabel["Llegada"] || "";
    initial.seat = byLabel["Asiento"] || "";
  } else if (type === "activity") {
    initial.activityTime = byLabel["Hora"] || "";
    initial.duration = byLabel["Duración"] || "";
    initial.meetingPoint = byLabel["Punto de encuentro"] || "";
  }
  return initial;
}

function AddItem({ trip, days, initialDay, onCancel, onSaved }) {
  const [dayMode, setDayMode] = useState("existing");
  const [day, setDay] = useState(initialDay);
  const [checkoutDay, setCheckoutDay] = useState(initialDay);
  const [newDate, setNewDate] = useState("");
  const [newCity, setNewCity] = useState("");
  const [type, setType] = useState("flight");
  const [source, setSource] = useState("");
  const [title, setTitle] = useState("");
  const [code, setCode] = useState("");
  const [mapsQuery, setMapsQuery] = useState("");
  const [customFields, setCustomFields] = useState([]);
  const [attachmentUrl, setAttachmentUrl] = useState("");
  const [file, setFile] = useState(null);
  const [saving, setSaving] = useState(false);
  const [toast, setToast] = useState(null);
  const { fields: f, buildMeta } = useTypeFields(type);

  const notify = (message, type = "error") => setToast({ message, type });

  const canSave = title.trim() && (dayMode === "existing" || (newDate.trim() && newCity.trim()));

  // Para "hotel" en modo día existente, la reserva se replica en todos los
  // días entre el check-in y el check-out (inclusive), para que al entrar a
  // cualquiera de esos días el alojamiento ya aparezca ahí, con las mismas
  // fechas de check-in/check-out de la estadía completa (no una fecha por día).
  const isMultiDayHotel = type === "hotel" && dayMode === "existing";

  const submit = async () => {
    setSaving(true);
    let dayIds = [];

    if (isMultiDayHotel) {
      const startNum = Math.min(day, checkoutDay);
      const endNum = Math.max(day, checkoutDay);
      dayIds = days
        .filter((d) => d.day_number >= startNum && d.day_number <= endNum)
        .sort((a, b) => a.day_number - b.day_number)
        .map((d) => d.id);
      if (dayIds.length === 0) {
        notify("No encontré días en ese rango.");
        setSaving(false);
        return;
      }
    } else if (dayMode === "existing") {
      const dayId = days.find((d) => d.day_number === day)?.id;
      if (!dayId) { notify("No encontré ese día."); setSaving(false); return; }
      dayIds = [dayId];
    } else {
      const nextNum = Math.max(0, ...days.map((d) => d.day_number)) + 1;
      const { data, error } = await supabase.from("trip_days")
        .insert({ trip_id: trip.id, day_number: nextNum, date_label: newDate.trim(), city: newCity.trim() })
        .select().single();
      if (error) { notify(error.message); setSaving(false); return; }
      dayIds = [data.id];
    }

    let finalAttachmentUrl = attachmentUrl.trim() || null;
    if (file) {
      const path = `${trip.id}/${Date.now()}-${file.name}`;
      const { error: upErr } = await supabase.storage.from("vouchers").upload(path, file);
      if (upErr) { notify("No se pudo subir el archivo: " + upErr.message); }
      else {
        const { data: pub } = supabase.storage.from("vouchers").getPublicUrl(path);
        finalAttachmentUrl = pub.publicUrl;
      }
    }

    const meta = buildMeta();
    customFields.forEach((cf) => {
      if (cf.label.trim() && cf.value.trim()) meta.push({ label: cf.label.trim(), value: cf.value.trim() });
    });

    // Mismo código de reserva para todas las filas generadas, así quedan
    // agrupadas como una sola reserva repartida en varios días.
    const sharedCode = code || genCode();
    const rows = dayIds.map((dayId) => ({
      day_id: dayId, type, source: source || "Manual", title: title.trim(),
      meta, code: sharedCode, maps_query: mapsQuery.trim(),
      voucher_label: "Ver reserva", attachment_url: finalAttachmentUrl,
    }));

    const { error } = await supabase.from("trip_items").insert(rows);
    setSaving(false);
    if (error) { notify(error.message); return; }
    onSaved();
  };

  return (
    <div className="min-h-screen" style={{ background: C.bg }}>
      <header className="px-5 pt-6 pb-4 flex items-center justify-between" style={{ borderBottom: `1px solid ${C.platinum}` }}>
        <h1 className="text-[19px] font-bold" style={{ color: C.ink }}>Nueva reserva</h1>
        <button onClick={onCancel} style={{ color: C.inkSoft }}><X size={20} /></button>
      </header>

      <main className="px-5 py-5 flex flex-col gap-4">
        <div>
          <label className="block text-[10px] uppercase mb-2" style={{ color: C.inkSoft }}>Tipo</label>
          <div className="flex gap-2 flex-wrap">
            {Object.entries(TYPE_STYLES).map(([key, s]) => {
              const Icon = s.icon; const active = type === key;
              return (
                <button key={key} onClick={() => setType(key)} className="flex items-center gap-1.5 text-[12px] font-semibold px-3 py-2 rounded-full"
                  style={{ background: active ? s.accent : C.card, color: active ? "#fff" : C.ink, border: `1px solid ${active ? s.accent : C.platinum}` }}>
                  <Icon size={13} /> {s.label}
                </button>
              );
            })}
          </div>
        </div>

        <div>
          <label className="block text-[10px] uppercase mb-2" style={{ color: C.inkSoft }}>Día</label>
          <div className="flex gap-2 mb-2">
            <button onClick={() => setDayMode("existing")} className="flex-1 text-[12px] font-semibold py-2 rounded-lg" style={{ background: dayMode === "existing" ? C.copper : C.card, color: dayMode === "existing" ? "#fff" : C.ink, border: `1px solid ${C.platinum}` }}>Día existente</button>
            <button onClick={() => setDayMode("new")} className="flex-1 text-[12px] font-semibold py-2 rounded-lg" style={{ background: dayMode === "new" ? C.copper : C.card, color: dayMode === "new" ? "#fff" : C.ink, border: `1px solid ${C.platinum}` }}>Día nuevo</button>
          </div>
          {dayMode === "existing" ? (
            <>
              <select value={day} onChange={(e) => { const v = Number(e.target.value); setDay(v); if (type === "hotel" && checkoutDay < v) setCheckoutDay(v); }} className="w-full text-[14px] p-3 rounded-lg outline-none" style={{ background: C.card, border: `1px solid ${C.platinum}`, color: C.ink }}>
                {days.map((d) => <option key={d.day_number} value={d.day_number}>Día {d.day_number} · {d.date_label} · {d.city}</option>)}
              </select>
              {type === "hotel" && (
                <>
                  <label className="block text-[10px] uppercase mt-2 mb-1" style={{ color: C.inkSoft }}>Hasta qué día (check-out)</label>
                  <select value={checkoutDay} onChange={(e) => setCheckoutDay(Number(e.target.value))} className="w-full text-[14px] p-3 rounded-lg outline-none" style={{ background: C.card, border: `1px solid ${C.platinum}`, color: C.ink }}>
                    {days.filter((d) => d.day_number >= day).map((d) => <option key={d.day_number} value={d.day_number}>Día {d.day_number} · {d.date_label} · {d.city}</option>)}
                  </select>
                  <p className="text-[10px] mt-1" style={{ color: C.inkSoft }}>
                    El alojamiento va a aparecer en todos los días del {day} al {checkoutDay}, con el mismo check-in y check-out.
                  </p>
                </>
              )}
            </>
          ) : (
            <div className="flex gap-2">
              <input value={newDate} onChange={(e) => setNewDate(e.target.value)} placeholder="Fecha" className="flex-1 text-[14px] p-3 rounded-lg outline-none" style={{ background: C.card, border: `1px solid ${C.platinum}`, color: C.ink }} />
              <input value={newCity} onChange={(e) => setNewCity(e.target.value)} placeholder="Ciudad" className="flex-1 text-[14px] p-3 rounded-lg outline-none" style={{ background: C.card, border: `1px solid ${C.platinum}`, color: C.ink }} />
            </div>
          )}
        </div>

        <Field label="Título" value={title} onChange={setTitle} placeholder="Ej: Vuelo AR1130 a Madrid" />
        <Field label="Fuente" value={source} onChange={setSource} placeholder="Booking, Despegar, Airbnb..." />

        {type === "flight" && (
          <div className="flex flex-col gap-3 p-3 rounded-lg" style={{ background: C.card, border: `1px solid ${C.platinum}` }}>
            <div className="flex gap-2">
              <Field label="Aerolínea" value={f.airline} onChange={f.setAirline} placeholder="Aerolíneas Argentinas" />
              <Field label="Número de vuelo" value={f.flightNumber} onChange={f.setFlightNumber} placeholder="IB5674" />
            </div>
            <div className="flex gap-2">
              <Field label="Aeropuerto de salida" value={f.departureAirport} onChange={f.setDepartureAirport} placeholder="Ezeiza (EZE)" />
              <Field label="Terminal de salida" value={f.departureTerminal} onChange={f.setDepartureTerminal} placeholder="Terminal A" />
            </div>
            <Field label="Hora de salida" value={f.departureTime} onChange={f.setDepartureTime} placeholder="23:40" />
            <div className="flex gap-2">
              <Field label="Aeropuerto de llegada" value={f.arrivalAirport} onChange={f.setArrivalAirport} placeholder="Barajas (MAD)" />
              <Field label="Terminal de llegada" value={f.arrivalTerminal} onChange={f.setArrivalTerminal} placeholder="Terminal 4" />
            </div>
            <div className="flex gap-2">
              <Field label="Fecha de llegada" value={f.arrivalDate} onChange={f.setArrivalDate} placeholder="4 de agosto" />
              <Field label="Hora de llegada" value={f.arrivalTime} onChange={f.setArrivalTime} placeholder="14:10" />
            </div>
            <p className="text-[10px] -mt-1.5" style={{ color: C.inkSoft }}>
              Si el vuelo llega al día siguiente, poné la fecha de llegada para no confundirte.
            </p>
            <Field label="Hora de embarque" value={f.boardingTime} onChange={f.setBoardingTime} placeholder="23:00" />
            <Toggle label="Tiene escala/conexión" checked={f.hasConnection} onChange={f.setHasConnection} />
            {f.hasConnection && (
              <Field label="Detalle de la escala" value={f.connectionDetail} onChange={f.setConnectionDetail} placeholder="Bogotá, 2h de espera" />
            )}
            <SelectField
              label="¿Incluye valijas?"
              value={f.baggageIncluded}
              onChange={f.setBaggageIncluded}
              options={[
                { value: "no_especificado", label: "No especificado" },
                { value: "si", label: "Sí" },
                { value: "no", label: "No" },
              ]}
            />
            <Toggle label="Check-in ya hecho" checked={f.checkinDone} onChange={f.setCheckinDone} />
          </div>
        )}

        {type === "hotel" && (
          <div className="flex flex-col gap-3 p-3 rounded-lg" style={{ background: C.card, border: `1px solid ${C.platinum}` }}>
            <div className="flex gap-2">
              <Field label="Check-in" value={f.checkInDateTime} onChange={f.setCheckInDateTime} placeholder="4 ago, 15:00" />
              <Field label="Check-out" value={f.checkOutDateTime} onChange={f.setCheckOutDateTime} placeholder="12 ago, 11:00" />
            </div>
            <Field label="Tipo de habitación (opcional)" value={f.roomType} onChange={f.setRoomType} placeholder="Doble con balcón" />
          </div>
        )}

        {type === "transport" && (
          <div className="flex flex-col gap-3 p-3 rounded-lg" style={{ background: C.card, border: `1px solid ${C.platinum}` }}>
            <Field label="Empresa / línea" value={f.operator} onChange={f.setOperator} placeholder="Flixbus, Renfe..." />
            <div className="flex gap-2">
              <Field label="Hora de salida" value={f.departureTime} onChange={f.setDepartureTime} placeholder="09:00" />
              <Field label="Hora de llegada" value={f.arrivalTime} onChange={f.setArrivalTime} placeholder="12:30" />
            </div>
            <Field label="Asiento (opcional)" value={f.seat} onChange={f.setSeat} placeholder="14A" />
          </div>
        )}

        {type === "activity" && (
          <div className="flex flex-col gap-3 p-3 rounded-lg" style={{ background: C.card, border: `1px solid ${C.platinum}` }}>
            <div className="flex gap-2">
              <Field label="Hora" value={f.activityTime} onChange={f.setActivityTime} placeholder="10:00" />
              <Field label="Duración (opcional)" value={f.duration} onChange={f.setDuration} placeholder="2h" />
            </div>
            <Field label="Punto de encuentro (opcional)" value={f.meetingPoint} onChange={f.setMeetingPoint} placeholder="Entrada principal" />
          </div>
        )}

        <CustomFieldsEditor fields={customFields} onChange={setCustomFields} />
        <Field label="Código de reserva" value={code} onChange={setCode} placeholder="Se genera solo si lo dejás vacío" />
        <Field
          label={type === "flight" ? "Aeropuerto para Maps (cómo llegar)" : "Dirección para Maps"}
          value={mapsQuery}
          onChange={setMapsQuery}
          placeholder={type === "flight" ? "Aeropuerto de Ezeiza, Buenos Aires" : "Hotel Atlántico Madrid, Gran Vía 38"}
        />
        <Field label="Link a comprobante (opcional)" value={attachmentUrl} onChange={setAttachmentUrl} placeholder="https://drive.google.com/..." />

        <div>
          <label className="flex items-center gap-1.5 text-[12px] font-semibold px-3 py-2 rounded-lg cursor-pointer w-fit" style={{ background: C.card, border: `1px solid ${C.platinum}`, color: C.ink }}>
            <Paperclip size={13} /> {file ? file.name : "O subir archivo (foto/PDF)"}
            <input type="file" accept="image/*,application/pdf" className="hidden" onChange={(e) => setFile(e.target.files?.[0] || null)} />
          </label>
        </div>

        <button onClick={submit} disabled={!canSave || saving} className="mt-2 w-full flex items-center justify-center gap-1.5 text-[14px] font-semibold text-white py-3.5 rounded-xl disabled:opacity-40" style={{ background: C.copper }}>
          {saving ? <Loader2 size={15} className="animate-spin" /> : "Guardar reserva"}
        </button>
      </main>
      <Toast toast={toast} onClose={() => setToast(null)} />
    </div>
  );
}

function Field({ label, value, onChange, placeholder }) {
  return (
    <div className="flex-1">
      <label className="block text-[10px] uppercase mb-1" style={{ color: C.inkSoft }}>{label}</label>
      <input value={value} onChange={(e) => onChange(e.target.value)} placeholder={placeholder}
        className="w-full text-[14px] p-3 rounded-lg outline-none" style={{ background: C.card, border: `1px solid ${C.platinum}`, color: C.ink }} />
    </div>
  );
}

/* Etiquetas de meta que ya sabemos reconstruir en el formulario, por tipo.
   Cualquier otra etiqueta que ya estuviera guardada (ej. "Otro detalle" viejo)
   se conserva tal cual al editar, en vez de perderse. */
const KNOWN_META_LABELS = {
  flight: ["Aerolínea", "Número de vuelo", "Aeropuerto de salida", "Terminal de salida", "Hora de salida", "Salida",
    "Aeropuerto de llegada", "Terminal de llegada", "Fecha de llegada", "Hora de llegada", "Llegada",
    "Embarque", "Escalas", "Equipaje incluido", "Check-in"],
  hotel: ["Check-in", "Check-out", "Habitación"],
  transport: ["Empresa", "Salida", "Llegada", "Asiento"],
  activity: ["Hora", "Duración", "Punto de encuentro"],
};

/* Editor de "otros detalles": antes era un único input que se reseteaba
   cada vez que se reabría el formulario de edición, así que cualquier
   detalle custom (ej. "Terminal para taxis") parecía desaparecer o se
   duplicaba/mezclaba con otro campo si se lo volvía a tipear. Ahora es una
   lista editable que se precarga con lo que ya estaba guardado. */
function CustomFieldsEditor({ fields, onChange }) {
  const addField = () => onChange([...fields, { key: `custom-${Date.now()}`, label: "", value: "" }]);
  const updateField = (key, prop, val) => onChange(fields.map((f) => (f.key === key ? { ...f, [prop]: val } : f)));
  const removeField = (key) => onChange(fields.filter((f) => f.key !== key));

  return (
    <div className="flex flex-col gap-2">
      <label className="block text-[10px] uppercase" style={{ color: C.inkSoft }}>Otros detalles (opcional)</label>
      {fields.map((f) => (
        <div key={f.key} className="flex gap-2 items-end">
          <Field label="Etiqueta" value={f.label} onChange={(v) => updateField(f.key, "label", v)} placeholder="Ej: Terminal para taxis" />
          <Field label="Valor" value={f.value} onChange={(v) => updateField(f.key, "value", v)} placeholder="Ej: Terminal 2" />
          <button onClick={() => removeField(f.key)} className="p-3 mb-0.5" style={{ color: "#B7391F" }} aria-label="Quitar detalle">
            <X size={16} />
          </button>
        </div>
      ))}
      <button onClick={addField} className="flex items-center gap-1.5 text-[12px] font-semibold py-2 w-fit" style={{ color: C.copper }}>
        <Plus size={13} /> Agregar otro detalle
      </button>
    </div>
  );
}

/* ---------- EditItem: editar una reserva ya cargada ---------- */

function EditItem({ item, day, days, onCancel, onSaved }) {
  const [type, setType] = useState(item.type);
  const [dayId, setDayId] = useState(item.day_id);
  const [source, setSource] = useState(item.source || "");
  const [title, setTitle] = useState(item.title || "");
  const [code, setCode] = useState(item.code || "");
  const [mapsQuery, setMapsQuery] = useState(item.maps_query || "");
  const [customFields, setCustomFields] = useState(() =>
    (item.meta || [])
      .filter((m) => !(KNOWN_META_LABELS[item.type] || []).includes(m.label))
      .map((m, i) => ({ key: `existing-${item.id}-${i}`, label: m.label, value: m.value }))
  );
  const [attachmentUrl, setAttachmentUrl] = useState(item.attachment_url || "");
  const [file, setFile] = useState(null);
  const [saving, setSaving] = useState(false);
  const [toast, setToast] = useState(null);
  const [confirmDelete, setConfirmDelete] = useState(false);
  const { fields: f, buildMeta } = useTypeFields(type, parseInitialFields(item.type, item.meta));

  const notify = (message, msgType = "error") => setToast({ message, type: msgType });

  const canSave = title.trim();

  const submit = async () => {
    setSaving(true);
    let finalAttachmentUrl = attachmentUrl.trim() || null;
    if (file) {
      const path = `${item.day_id}/${Date.now()}-${file.name}`;
      const { error: upErr } = await supabase.storage.from("vouchers").upload(path, file);
      if (upErr) { notify("No se pudo subir el archivo: " + upErr.message); }
      else {
        const { data: pub } = supabase.storage.from("vouchers").getPublicUrl(path);
        finalAttachmentUrl = pub.publicUrl;
      }
    }

    const meta = buildMeta();
    customFields.forEach((cf) => {
      if (cf.label.trim() && cf.value.trim()) meta.push({ label: cf.label.trim(), value: cf.value.trim() });
    });

    const { error } = await supabase.from("trip_items").update({
      type, day_id: dayId, source: source || "Manual", title: title.trim(),
      meta, code: code.trim() || item.code, maps_query: mapsQuery.trim(),
      attachment_url: finalAttachmentUrl,
    }).eq("id", item.id);
    setSaving(false);
    if (error) { notify(error.message); return; }
    onSaved();
  };

  const doDelete = async () => {
    const { error } = await supabase.from("trip_items").delete().eq("id", item.id);
    if (error) { notify(error.message); setConfirmDelete(false); return; }
    onSaved();
  };

  return (
    <div className="min-h-screen" style={{ background: C.bg }}>
      <header className="px-5 pt-6 pb-4 flex items-center justify-between" style={{ borderBottom: `1px solid ${C.platinum}` }}>
        <h1 className="text-[19px] font-bold" style={{ color: C.ink }}>Editar reserva</h1>
        <button onClick={onCancel} style={{ color: C.inkSoft }}><X size={20} /></button>
      </header>

      <main className="px-5 py-5 flex flex-col gap-4">
        {days && days.length > 0 ? (
          <div>
            <label className="block text-[10px] uppercase mb-2" style={{ color: C.inkSoft }}>Día</label>
            <select value={dayId} onChange={(e) => setDayId(e.target.value)}
              className="w-full text-[14px] p-3 rounded-lg outline-none" style={{ background: C.card, border: `1px solid ${C.platinum}`, color: C.ink }}>
              {days.map((d) => <option key={d.id} value={d.id}>Día {d.day_number} · {d.date_label} · {d.city}</option>)}
            </select>
          </div>
        ) : day && (
          <p className="text-[11px]" style={{ color: C.inkSoft }}>
            Día {day.day_number} · {day.date_label} · {day.city}
          </p>
        )}

        <div>
          <label className="block text-[10px] uppercase mb-2" style={{ color: C.inkSoft }}>Tipo</label>
          <div className="flex gap-2 flex-wrap">
            {Object.entries(TYPE_STYLES).map(([key, s]) => {
              const Icon = s.icon; const active = type === key;
              return (
                <button key={key} onClick={() => setType(key)} className="flex items-center gap-1.5 text-[12px] font-semibold px-3 py-2 rounded-full"
                  style={{ background: active ? s.accent : C.card, color: active ? "#fff" : C.ink, border: `1px solid ${active ? s.accent : C.platinum}` }}>
                  <Icon size={13} /> {s.label}
                </button>
              );
            })}
          </div>
        </div>

        <Field label="Título" value={title} onChange={setTitle} placeholder="Ej: Vuelo AR1130 a Madrid" />
        <Field label="Fuente" value={source} onChange={setSource} placeholder="Booking, Despegar, Airbnb..." />

        {type === "flight" && (
          <div className="flex flex-col gap-3 p-3 rounded-lg" style={{ background: C.card, border: `1px solid ${C.platinum}` }}>
            <div className="flex gap-2">
              <Field label="Aerolínea" value={f.airline} onChange={f.setAirline} placeholder="Aerolíneas Argentinas" />
              <Field label="Número de vuelo" value={f.flightNumber} onChange={f.setFlightNumber} placeholder="IB5674" />
            </div>
            <div className="flex gap-2">
              <Field label="Aeropuerto de salida" value={f.departureAirport} onChange={f.setDepartureAirport} placeholder="Ezeiza (EZE)" />
              <Field label="Terminal de salida" value={f.departureTerminal} onChange={f.setDepartureTerminal} placeholder="Terminal A" />
            </div>
            <Field label="Hora de salida" value={f.departureTime} onChange={f.setDepartureTime} placeholder="23:40" />
            <div className="flex gap-2">
              <Field label="Aeropuerto de llegada" value={f.arrivalAirport} onChange={f.setArrivalAirport} placeholder="Barajas (MAD)" />
              <Field label="Terminal de llegada" value={f.arrivalTerminal} onChange={f.setArrivalTerminal} placeholder="Terminal 4" />
            </div>
            <div className="flex gap-2">
              <Field label="Fecha de llegada" value={f.arrivalDate} onChange={f.setArrivalDate} placeholder="4 de agosto" />
              <Field label="Hora de llegada" value={f.arrivalTime} onChange={f.setArrivalTime} placeholder="14:10" />
            </div>
            <p className="text-[10px] -mt-1.5" style={{ color: C.inkSoft }}>
              Si el vuelo llega al día siguiente, poné la fecha de llegada para no confundirte.
            </p>
            <Field label="Hora de embarque" value={f.boardingTime} onChange={f.setBoardingTime} placeholder="23:00" />
            <Toggle label="Tiene escala/conexión" checked={f.hasConnection} onChange={f.setHasConnection} />
            {f.hasConnection && (
              <Field label="Detalle de la escala" value={f.connectionDetail} onChange={f.setConnectionDetail} placeholder="Bogotá, 2h de espera" />
            )}
            <SelectField
              label="¿Incluye valijas?"
              value={f.baggageIncluded}
              onChange={f.setBaggageIncluded}
              options={[
                { value: "no_especificado", label: "No especificado" },
                { value: "si", label: "Sí" },
                { value: "no", label: "No" },
              ]}
            />
            <Toggle label="Check-in ya hecho" checked={f.checkinDone} onChange={f.setCheckinDone} />
          </div>
        )}

        {type === "hotel" && (
          <div className="flex flex-col gap-3 p-3 rounded-lg" style={{ background: C.card, border: `1px solid ${C.platinum}` }}>
            <div className="flex gap-2">
              <Field label="Check-in" value={f.checkInDateTime} onChange={f.setCheckInDateTime} placeholder="4 ago, 15:00" />
              <Field label="Check-out" value={f.checkOutDateTime} onChange={f.setCheckOutDateTime} placeholder="12 ago, 11:00" />
            </div>
            <Field label="Tipo de habitación (opcional)" value={f.roomType} onChange={f.setRoomType} placeholder="Doble con balcón" />
          </div>
        )}

        {type === "transport" && (
          <div className="flex flex-col gap-3 p-3 rounded-lg" style={{ background: C.card, border: `1px solid ${C.platinum}` }}>
            <Field label="Empresa / línea" value={f.operator} onChange={f.setOperator} placeholder="Flixbus, Renfe..." />
            <div className="flex gap-2">
              <Field label="Hora de salida" value={f.departureTime} onChange={f.setDepartureTime} placeholder="09:00" />
              <Field label="Hora de llegada" value={f.arrivalTime} onChange={f.setArrivalTime} placeholder="12:30" />
            </div>
            <Field label="Asiento (opcional)" value={f.seat} onChange={f.setSeat} placeholder="14A" />
          </div>
        )}

        {type === "activity" && (
          <div className="flex flex-col gap-3 p-3 rounded-lg" style={{ background: C.card, border: `1px solid ${C.platinum}` }}>
            <div className="flex gap-2">
              <Field label="Hora" value={f.activityTime} onChange={f.setActivityTime} placeholder="10:00" />
              <Field label="Duración (opcional)" value={f.duration} onChange={f.setDuration} placeholder="2h" />
            </div>
            <Field label="Punto de encuentro (opcional)" value={f.meetingPoint} onChange={f.setMeetingPoint} placeholder="Entrada principal" />
          </div>
        )}

        <CustomFieldsEditor fields={customFields} onChange={setCustomFields} />
        <Field label="Código de reserva" value={code} onChange={setCode} placeholder={item.code} />
        <Field
          label={type === "flight" ? "Aeropuerto para Maps (cómo llegar)" : "Dirección para Maps"}
          value={mapsQuery}
          onChange={setMapsQuery}
          placeholder={type === "flight" ? "Aeropuerto de Ezeiza, Buenos Aires" : "Hotel Atlántico Madrid, Gran Vía 38"}
        />
        <Field label="Link a comprobante (opcional)" value={attachmentUrl} onChange={setAttachmentUrl} placeholder="https://drive.google.com/..." />

        <div>
          <label className="flex items-center gap-1.5 text-[12px] font-semibold px-3 py-2 rounded-lg cursor-pointer w-fit" style={{ background: C.card, border: `1px solid ${C.platinum}`, color: C.ink }}>
            <Paperclip size={13} /> {file ? file.name : "O subir archivo nuevo (foto/PDF)"}
            <input type="file" accept="image/*,application/pdf" className="hidden" onChange={(e) => setFile(e.target.files?.[0] || null)} />
          </label>
        </div>

        <button onClick={submit} disabled={!canSave || saving} className="mt-2 w-full flex items-center justify-center gap-1.5 text-[14px] font-semibold text-white py-3.5 rounded-xl disabled:opacity-40" style={{ background: C.copper }}>
          {saving ? <Loader2 size={15} className="animate-spin" /> : "Guardar cambios"}
        </button>
        <button onClick={() => setConfirmDelete(true)} className="text-[12px] font-semibold py-2" style={{ color: "#B7391F" }}>
          Eliminar reserva
        </button>
      </main>
      <Toast toast={toast} onClose={() => setToast(null)} />
      <ConfirmModal
        open={confirmDelete}
        title="Eliminar reserva"
        message={`¿Seguro que querés eliminar "${item.title}"? Esta acción no se puede deshacer.`}
        confirmLabel="Eliminar"
        danger
        onCancel={() => setConfirmDelete(false)}
        onConfirm={doDelete}
      />
    </div>
  );
}

function Toggle({ label, checked, onChange }) {
  return (
    <button
      type="button"
      onClick={() => onChange(!checked)}
      className="flex items-center justify-between text-[13px] font-medium py-1"
      style={{ color: C.ink }}
    >
      {label}
      <span
        className="relative inline-flex items-center rounded-full transition-colors"
        style={{ width: 38, height: 22, background: checked ? C.copper : C.platinum }}
      >
        <span
          className="absolute rounded-full bg-white transition-transform"
          style={{ width: 18, height: 18, left: 2, transform: checked ? "translateX(16px)" : "translateX(0)" }}
        />
      </span>
    </button>
  );
}

function SelectField({ label, value, onChange, options }) {
  return (
    <div className="flex-1">
      <label className="block text-[10px] uppercase mb-1" style={{ color: C.inkSoft }}>{label}</label>
      <select value={value} onChange={(e) => onChange(e.target.value)}
        className="w-full text-[14px] p-3 rounded-lg outline-none" style={{ background: C.card, border: `1px solid ${C.platinum}`, color: C.ink }}>
        {options.map((o) => <option key={o.value} value={o.value}>{o.label}</option>)}
      </select>
    </div>
  );
}

/* ---------- Importación masiva de itinerario ----------
   Pega un JSON con la forma:
   [
     { "day_number": 1, "date_label": "Mié 5 ago", "city": "París",
       "items": [
         { "type": "activity", "source": "Manual", "title": "Torre Eiffel",
           "code": "", "maps_query": "Torre Eiffel, Paris",
           "meta": [ { "label": "Hora", "value": "14:15" } ] }
       ]
     }
   ]
   Tipos válidos: flight, hotel, transport, activity.
   Si ya existe un día con el mismo day_number, se reutiliza (no se
   duplica) y los items nuevos se agregan a los que ya tenga. */
function BulkImport({ trip, days, onCancel, onSaved }) {
  const EXAMPLE = `[
  {
    "day_number": 1,
    "date_label": "Mié 5 ago",
    "city": "París",
    "items": [
      {
        "type": "activity",
        "source": "Itinerario",
        "title": "Torre Eiffel",
        "code": "",
        "maps_query": "Torre Eiffel, Paris",
        "meta": [
          { "label": "Hora", "value": "14:15" },
          { "label": "Punto de encuentro", "value": "Jardines del Trocadéro" }
        ]
      }
    ]
  }
]`;
  const [raw, setRaw] = useState("");
  const [parsed, setParsed] = useState(null);
  const [parseError, setParseError] = useState("");
  const [importing, setImporting] = useState(false);
  const [toast, setToast] = useState(null);
  const [lastBatch, setLastBatch] = useState(null); // { itemIds, newDayIds } de la última importación
  const [undoing, setUndoing] = useState(false);
  const [removeSource, setRemoveSource] = useState("Itinerario");
  const [confirmRemoveSource, setConfirmRemoveSource] = useState(false);
  const [removingSource, setRemovingSource] = useState(false);
  const notify = (message, type = "error") => setToast({ message, type });

  const doParse = () => {
    setParseError("");
    setParsed(null);
    try {
      const data = JSON.parse(raw);
      if (!Array.isArray(data)) throw new Error("El JSON debe ser un array de días.");
      data.forEach((d, i) => {
        if (typeof d.day_number !== "number") throw new Error(`Día #${i + 1}: falta "day_number" numérico.`);
        if (!d.date_label) throw new Error(`Día #${i + 1}: falta "date_label".`);
        if (!Array.isArray(d.items)) throw new Error(`Día #${i + 1}: falta el array "items".`);
      });
      setParsed(data);
    } catch (e) {
      setParseError(e.message || "JSON inválido.");
    }
  };

  const totalItems = parsed ? parsed.reduce((acc, d) => acc + d.items.length, 0) : 0;

  const runImport = async () => {
    if (!parsed) return;
    setImporting(true);
    const insertedItemIds = [];
    const newDayIds = [];
    try {
      for (const d of parsed) {
        let dayId = days.find((x) => x.day_number === d.day_number)?.id;
        if (!dayId) {
          const { data: newDay, error: dayErr } = await supabase.from("trip_days")
            .insert({ trip_id: trip.id, day_number: d.day_number, date_label: d.date_label.trim(), city: (d.city || "Sin definir").trim() })
            .select().single();
          if (dayErr) throw dayErr;
          dayId = newDay.id;
          newDayIds.push(dayId);
        }
        if (d.items.length) {
          const rows = d.items.map((it) => ({
            day_id: dayId,
            type: TYPE_STYLES[it.type] ? it.type : "activity",
            source: it.source || "Itinerario",
            title: (it.title || "Sin título").trim(),
            meta: Array.isArray(it.meta) ? it.meta : [],
            code: it.code || genCode(),
            maps_query: it.maps_query || "",
            voucher_label: "Ver reserva",
            attachment_url: it.attachment_url || null,
          }));
          const { data: insertedRows, error: itemsErr } = await supabase.from("trip_items").insert(rows).select("id");
          if (itemsErr) throw itemsErr;
          (insertedRows || []).forEach((r) => insertedItemIds.push(r.id));
        }
      }
      setImporting(false);
      setLastBatch({ itemIds: insertedItemIds, newDayIds, dayCount: parsed.length, itemCount: insertedItemIds.length });
      notify(`Se importaron ${insertedItemIds.length} reserva(s)/actividad(es) en ${parsed.length} día(s).`, "success");
    } catch (e) {
      setImporting(false);
      notify(e.message || "No se pudo importar.");
    }
  };

  const undoLastBatch = async () => {
    if (!lastBatch) return;
    setUndoing(true);
    try {
      if (lastBatch.itemIds.length) {
        const { error: delItemsErr } = await supabase.from("trip_items").delete().in("id", lastBatch.itemIds);
        if (delItemsErr) throw delItemsErr;
      }
      for (const dId of lastBatch.newDayIds) {
        const { count } = await supabase.from("trip_items").select("id", { count: "exact", head: true }).eq("day_id", dId);
        if (!count) await supabase.from("trip_days").delete().eq("id", dId);
      }
      setUndoing(false);
      setLastBatch(null);
      notify("Se deshizo la última importación.", "success");
      onSaved();
    } catch (e) {
      setUndoing(false);
      notify(e.message || "No se pudo deshacer la importación.");
    }
  };

  const removeBySource = async () => {
    setRemovingSource(true);
    try {
      const { data: tripDays, error: daysErr } = await supabase.from("trip_days").select("id").eq("trip_id", trip.id);
      if (daysErr) throw daysErr;
      const dayIds = (tripDays || []).map((d) => d.id);
      const { error } = await supabase.from("trip_items").delete().eq("source", removeSource.trim()).in("day_id", dayIds.length ? dayIds : ["00000000-0000-0000-0000-000000000000"]);
      if (error) throw error;
      setRemovingSource(false);
      setConfirmRemoveSource(false);
      notify(`Se eliminaron los items con fuente "${removeSource.trim()}".`, "success");
      onSaved();
    } catch (e) {
      setRemovingSource(false);
      notify(e.message || "No se pudo eliminar.");
    }
  };

  return (
    <div className="min-h-screen" style={{ background: C.bg }}>
      <header className="px-5 pt-6 pb-4 flex items-center justify-between" style={{ borderBottom: `1px solid ${C.platinum}` }}>
        <h1 className="text-[19px] font-bold" style={{ color: C.ink }}>Importar itinerario</h1>
        <button onClick={onCancel} style={{ color: C.inkSoft }}><X size={20} /></button>
      </header>

      <main className="px-5 py-5 flex flex-col gap-4">
        <p className="text-[12px]" style={{ color: C.inkSoft }}>
          Pegá acá el JSON con los días y las reservas/actividades. Se crean los días que
          falten (por <code>day_number</code>) y se agregan los items a los días existentes
          sin borrar lo que ya cargaste.
        </p>

        <textarea
          value={raw}
          onChange={(e) => { setRaw(e.target.value); setParsed(null); setParseError(""); }}
          placeholder={EXAMPLE}
          rows={14}
          className="w-full text-[12px] font-mono p-3 rounded-lg outline-none"
          style={{ background: C.card, border: `1px solid ${C.platinum}`, color: C.ink }}
        />

        {parseError && (
          <div className="flex items-start gap-2 text-[12px] p-3 rounded-lg" style={{ background: "#FBEAEA", color: "#8A2A2A" }}>
            <AlertCircle size={14} className="mt-0.5 flex-shrink-0" /> {parseError}
          </div>
        )}

        {lastBatch ? (
          <div className="flex flex-col gap-2 p-3 rounded-lg" style={{ background: C.wheat, border: `1px solid ${C.platinum}` }}>
            <p className="text-[12px] font-semibold" style={{ color: C.ink }}>
              Se importaron {lastBatch.itemCount} item(s) en {lastBatch.dayCount} día(s).
            </p>
            <p className="text-[11px]" style={{ color: C.inkSoft }}>
              Si algo quedó en el día equivocado, tocá el ícono de lápiz de esa reserva
              y cambiá el campo "Día". Si preferís deshacer toda esta importación, usá el botón de abajo.
            </p>
            <div className="flex gap-2 mt-1">
              <button onClick={undoLastBatch} disabled={undoing} className="flex-1 flex items-center justify-center gap-1.5 text-[13px] font-semibold py-3 rounded-xl disabled:opacity-60" style={{ background: "#FBEAEA", color: "#8A2A2A" }}>
                {undoing ? <Loader2 size={15} className="animate-spin" /> : <Trash2 size={15} />} Deshacer esta importación
              </button>
              <button onClick={() => { setLastBatch(null); setRaw(""); setParsed(null); onSaved(); }} className="flex-1 text-[13px] font-semibold py-3 rounded-xl" style={{ background: C.copper, color: "#fff" }}>
                Listo, volver al viaje
              </button>
            </div>
          </div>
        ) : !parsed ? (
          <button onClick={doParse} disabled={!raw.trim()} className="w-full text-[13px] font-semibold py-3 rounded-xl disabled:opacity-40" style={{ background: C.wheat, color: C.ink }}>
            Previsualizar
          </button>
        ) : (
          <>
            <div className="flex flex-col gap-2 p-3 rounded-lg" style={{ background: C.card, border: `1px solid ${C.platinum}` }}>
              <p className="text-[12px] font-semibold" style={{ color: C.ink }}>
                {parsed.length} día(s) · {totalItems} reserva(s)/actividad(es)
              </p>
              {parsed.map((d) => (
                <div key={d.day_number} className="text-[12px]" style={{ color: C.inkSoft }}>
                  Día {d.day_number} · {d.date_label} · {d.city || "Sin definir"} — {d.items.length} item(s)
                  {days.find((x) => x.day_number === d.day_number) && <span> (día ya existe, se agregan items)</span>}
                </div>
              ))}
            </div>
            <div className="flex gap-2">
              <button onClick={() => setParsed(null)} className="flex-1 text-[13px] font-semibold py-3 rounded-xl" style={{ background: C.card, color: C.ink, border: `1px solid ${C.platinum}` }}>
                Volver a editar
              </button>
              <button onClick={runImport} disabled={importing} className="flex-1 flex items-center justify-center gap-1.5 text-[13px] font-semibold py-3 rounded-xl disabled:opacity-60" style={{ background: C.copper, color: "#fff" }}>
                {importing ? <Loader2 size={15} className="animate-spin" /> : <Check size={15} />} Importar todo
              </button>
            </div>
          </>
        )}

        {!lastBatch && (
          <div className="mt-4 pt-4 flex flex-col gap-2" style={{ borderTop: `1px dashed ${C.platinum}` }}>
            <p className="text-[11px] font-semibold uppercase" style={{ color: C.inkSoft }}>Borrar una importación anterior</p>
            <p className="text-[11px]" style={{ color: C.inkSoft }}>
              Esto elimina todas las reservas/actividades cuya "fuente" coincida con el texto de abajo
              (por defecto, todo lo que se cargó como "Itinerario"). Los días no se borran.
            </p>
            <div className="flex gap-2">
              <input value={removeSource} onChange={(e) => setRemoveSource(e.target.value)} placeholder="Itinerario"
                className="flex-1 text-[13px] p-3 rounded-lg outline-none" style={{ background: C.card, border: `1px solid ${C.platinum}`, color: C.ink }} />
              <button onClick={() => setConfirmRemoveSource(true)} disabled={!removeSource.trim()} className="flex items-center gap-1.5 text-[13px] font-semibold px-4 py-3 rounded-xl disabled:opacity-40" style={{ background: "#FBEAEA", color: "#8A2A2A" }}>
                <Trash2 size={14} /> Borrar
              </button>
            </div>
          </div>
        )}
      </main>

      <ConfirmModal
        open={confirmRemoveSource}
        title="Borrar items importados"
        message={`¿Seguro que querés eliminar todas las reservas/actividades con fuente "${removeSource.trim()}" en este viaje? Esta acción no se puede deshacer.`}
        confirmLabel={removingSource ? "Eliminando..." : "Eliminar"}
        danger
        onCancel={() => setConfirmRemoveSource(false)}
        onConfirm={removeBySource}
      />

      <Toast toast={toast} onClose={() => setToast(null)} />
    </div>
  );
}

export default function App() {
  const [session, setSession] = useState(undefined);
  const [tripId, setTripId] = useState(null);

  useEffect(() => {
    supabase.auth.getSession().then(({ data }) => setSession(data.session));
    const { data: sub } = supabase.auth.onAuthStateChange((_e, s) => setSession(s));
    return () => sub.subscription.unsubscribe();
  }, []);

  let content;
  if (session === undefined) {
    content = <div className="min-h-screen flex items-center justify-center" style={{ background: C.bg }}><Loader2 className="animate-spin" color={C.copper} /></div>;
  } else if (!session) {
    content = <AuthScreen />;
  } else if (tripId) {
    content = <TripView tripId={tripId} onBack={() => setTripId(null)} />;
  } else {
    content = <TripsHome user={session.user} onOpenTrip={setTripId} />;
  }

  return (
    <>
      <GlobalFonts />
      {content}
    </>
  );
}
